import {Popover, Stack, Button, Heading, Portal} from '@primer/react'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {useLayoutEffect, useRef, type RefObject} from 'react'
import styles from './CCAPopover.module.css'

interface FreeUserPopoverProps {
  showPopover: boolean
  dismissPopover: () => void
  anchorRef: RefObject<HTMLElement | null>
}

export function FreeUserPopover({showPopover, dismissPopover, anchorRef}: FreeUserPopoverProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const popoverRef = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    if (!showPopover || !anchorRef.current || !popoverRef.current) return

    const anchorRect = anchorRef.current.getBoundingClientRect()
    const popover = popoverRef.current
    const popoverRect = popover.getBoundingClientRect()

    // Position the popover below the anchor, centered horizontally over the anchor
    const anchorCenterX = anchorRect.left + anchorRect.width / 2
    const popoverLeft = anchorCenterX - popoverRect.width / 2

    popover.style.position = 'fixed'
    popover.style.top = `${anchorRect.bottom + 8}px`
    popover.style.left = `${popoverLeft}px`
  }, [showPopover, anchorRef])

  if (!showPopover) {
    return null
  }

  const agentName = 'Copilot cloud agent'

  const handleDismissClick = () => {
    sendClickAnalyticsEvent({
      category: 'copilot-coding-agent-free-popover',
      action: 'dismiss',
      tag: 'button',
      group: 'expand',
      location: 'global-copilot-menu',
    })
    dismissPopover()
  }
  return (
    <Portal>
      <div ref={popoverRef} className={styles.popover_wrapper}>
        <Popover open={showPopover} caret="top" className={styles.popover}>
          <Popover.Content
            className={styles.popover_content}
            data-analytics-visible={JSON.stringify({
              category: 'copilot-coding-agent-free-popover',
              action: 'visible',
              group: 'expand',
              location: 'global-copilot-menu',
            })}
          >
            <Heading as="h3" variant="small" className="h5 mb-1">
              Start a task with {agentName}
            </Heading>
            <p>
              Copilot works in the cloud and opens a pull request for your review. Enjoy up to 5 free uses this month
              with your Copilot Free plan.
            </p>
            <Stack className="mt-2" direction="horizontal" gap="condensed">
              <Button onClick={handleDismissClick}>Dismiss</Button>
            </Stack>
          </Popover.Content>
        </Popover>
      </div>
    </Portal>
  )
}
