import styles from './GlobalCopilotOverlay.module.css'
import {ActionList, IconButton, Link, RelativeTime} from '@primer/react'
import {SkeletonAvatar, SkeletonText} from '@primer/react/experimental'
import {AlertIcon, ArrowUpRightIcon, DotFillIcon, XIcon} from '@primer/octicons-react'
import {
  useTasks,
  getAgentTasksQueryKeyForMutation,
  getFlatTaskList,
  setFlatTaskList,
  PAGE_SIZE,
  type FetchTasksResponse,
} from '@github-ui/agent-sessions/hooks/useTasks'
import {useCreateAPITask} from '@github-ui/agent-sessions/hooks/use-create-api-task'
import {useCreateLocalDeviceSession} from '@github-ui/agent-sessions/hooks/use-create-local-device-session'
import {WithShimmerEffect} from '@github-ui/copilot-chat/components/WithShimmerEffect'
import {useSSOChangeDetection} from '@github-ui/agent-sessions/hooks/useSSOChangeDetection'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {useCurrentRepository} from '@github-ui/current-repository'
import {NewAgentTaskForm} from '@github-ui/new-agent-task-form/NewAgentTaskForm'
import {memo, useCallback, useMemo, useState} from 'react'
import {TaskLeadingVisual} from '@github-ui/agent-sessions/components/TaskLeadingVisual'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {generateTaskPathForRepo} from '@github-ui/agent-sessions/utils/generate-task-path'
import {resolveAgentProfile} from '@github-ui/agent-sessions/agents/resolve-agent-profile'
import {sendEvent} from '@github-ui/hydro-analytics'
import {getTaskTitle} from '@github-ui/agent-sessions/utils/task-helpers'

import type {HydratedTask, OptimisticTask, UITask} from '@github-ui/agent-sessions/types/task'
import {getReadableSessionState, type SessionState} from '@github-ui/agent-sessions/types/session'
import {
  type FailedAPITaskCreationAttempt,
  TaskCreationFailedBannerList,
  getAPITaskParamsFromAttempt,
} from '@github-ui/agent-sessions/components/TaskCreationFailedBanner'

export function GlobalCopilotOverlay({onClose}: {onClose?: () => void}) {
  // Detect SSO changes and clear cached tasks
  useSSOChangeDetection()

  const {tasks, isLoading, isError} = useTasks({taskFilter: 'active'})
  const [failedTasks, setFailedTasks] = useState<FailedAPITaskCreationAttempt[]>([])

  // Read initial text and branch from localStorage (set by external triggers like FixWorkflowButton)
  const [{initialText, initialBranch}] = useState<{initialText?: string; initialBranch?: string}>(() => {
    const entrypointMessage = copilotLocalStorage.getTaskEntrypointMessage()
    if (entrypointMessage?.message) {
      copilotLocalStorage.setTaskEntrypointMessage(null)
      return {initialText: entrypointMessage.message, initialBranch: entrypointMessage.branch}
    }
    return {}
  })

  const taskListMutationConfig = useMemo(
    () => ({
      queryKey: getAgentTasksQueryKeyForMutation(),
      pageSize: PAGE_SIZE,
      getFlatTaskList,
      setFlatTaskList,
    }),
    [],
  )

  const {createTask} = useCreateAPITask<FetchTasksResponse>({
    ...taskListMutationConfig,
    onError: (error, variables) => {
      setFailedTasks(prev => [
        {
          ...variables,
          errorMessage: error.message,
          timestamp: new Date().toISOString(),
        },
        ...prev,
      ])
    },
  })

  const localDeviceMutation = useCreateLocalDeviceSession<FetchTasksResponse>({
    optimisticTaskListConfig: taskListMutationConfig,
  })
  const onLocalDeviceSubmit = localDeviceMutation.mutateAsync

  const handleRetry = (attemptIndex: number) => {
    const attempt = failedTasks[attemptIndex]
    if (attempt) {
      setFailedTasks(prev => prev.filter((_, index) => index !== attemptIndex))
      createTask(getAPITaskParamsFromAttempt(attempt))
    }
  }

  // Memoize the link click handler to prevent unnecessary re-renders
  const handleLinkClick = useCallback(
    (event: React.MouseEvent) => {
      // Only close if it's not a cmd+click (metaKey on Mac) or ctrl+click (ctrlKey on Windows/Linux)
      // These are used to open links in new tabs
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      const isModifiedClick = event.metaKey || event.ctrlKey
      if (!isModifiedClick && onClose) {
        onClose()
      }
    },
    [onClose],
  )

  const defaultToTaskInput = isFeatureEnabled('copilot_default_to_task_input')

  return (
    <div className={styles.overlay}>
      <div className={styles.header}>
        <h2 className="f5">Agents</h2>
        {defaultToTaskInput && (
          <div className="d-flex gap-2">
            <IconButton
              icon={ArrowUpRightIcon}
              aria-label="Navigate to Copilot"
              variant="invisible"
              size="small"
              as="a"
              href="/copilot/agents"
              onClick={e => {
                sendEvent('agent_sessions.global_agents_menu', {
                  target: 'NAVIGATE_TO_AGENTS_FULLSCREEN',
                  defaultToTaskInput,
                  defaultToTaskControl: isFeatureEnabled('copilot_default_to_task_input_control_group'),
                })
                handleLinkClick(e)
              }}
            />
            <IconButton icon={XIcon} aria-label="Close" variant="invisible" size="small" onClick={onClose} />
          </div>
        )}
      </div>
      <div className={styles.content}>
        <NewAgentTaskForm
          createTask={createTask}
          eventType="agents_panel"
          showHeader={false}
          initialText={initialText}
          initialBranch={initialBranch}
          onLocalDeviceSubmit={onLocalDeviceSubmit}
        />
        <TaskCreationFailedBannerList
          attempts={failedTasks}
          onRetry={handleRetry}
          onDismiss={index => setFailedTasks(prev => prev.filter((_, i) => i !== index))}
          className={styles.failedTaskBanners}
        />
        {isLoading && tasks.length === 0 ? (
          <TasksLoadingState />
        ) : (
          <>
            {isError ? (
              <TasksErrorState />
            ) : tasks.length === 0 ? (
              <TasksEmptyState />
            ) : (
              <TasksList tasks={tasks} onLinkClick={handleLinkClick} />
            )}
            <CopilotDisclosure />
          </>
        )}
      </div>
    </div>
  )
}

// There's an issue with ActionList.LinkItem/Item being unable to handle icon transitions properly unless we memoize the component
// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const TaskItem = memo(function TaskItem({
  taskId,
  isArchived,
  state,
  updatedAt,
  title,
  prState,
  prNumber,
  nwo,
  prGlobalId,
  prInMergeQueue,
  latestSessionId,
  onLinkClick,
  agentSlug,
  sharingStatus,
}: {
  taskId?: string
  isArchived?: boolean
  state: SessionState
  updatedAt: string
  title: string
  prState?: string
  prNumber?: number
  nwo?: string
  prGlobalId?: string
  prInMergeQueue?: boolean
  latestSessionId?: string
  onLinkClick: (event: React.MouseEvent) => void
  agentSlug?: string
  sharingStatus?: 'unshared' | 'shared'
}) {
  const agentProfile = resolveAgentProfile(agentSlug)
  const LeadingIcon = agentProfile.slots.LeadingIcon
  const TrailingVisual = agentProfile.slots.TrailingVisual
  const sessionFiltersEnabled = isFeatureEnabled('copilot_mission_control_session_filters')
  const EffectiveLeadingIcon = sessionFiltersEnabled ? null : LeadingIcon

  const taskUrl = generateTaskPathForRepo({
    repositoryNwo: nwo,
    pullRequestNumber: prNumber,
    sessionId: latestSessionId,
    taskId,
  })

  return (
    <ActionList.LinkItem
      className={styles.task}
      href={taskUrl}
      onClick={e => {
        onLinkClick(e)
        sendEvent('agent_sessions.global_agents_menu', {
          target: 'VIEW_TASK_FROM_AGENTS_MENU',
          task_id: prGlobalId,
        })
      }}
      size="large"
    >
      <ActionList.LeadingVisual>
        {EffectiveLeadingIcon ? (
          <EffectiveLeadingIcon
            state={state}
            prState={prState}
            prInMergeQueue={prInMergeQueue}
            isArchived={isArchived}
          />
        ) : (
          <TaskLeadingVisual
            prState={prState}
            prInMergeQueue={prInMergeQueue}
            sessionState={state}
            isArchived={isArchived}
          />
        )}
      </ActionList.LeadingVisual>
      {title}
      <ActionList.Description variant="block" className="no-wrap">
        {nwo ?? getReadableSessionState(state)}
        {updatedAt && (
          <>
            {' '}
            · <RelativeTime datetime={updatedAt} format="micro" className={styles.taskStartDate} />
          </>
        )}
      </ActionList.Description>
      {sessionFiltersEnabled && TrailingVisual && (
        <ActionList.TrailingVisual className={styles.trailingVisual}>
          <TrailingVisual state={state} sharingStatus={sharingStatus} />
        </ActionList.TrailingVisual>
      )}
    </ActionList.LinkItem>
  )
})

function TasksList({tasks, onLinkClick}: {tasks: UITask[]; onLinkClick: (event: React.MouseEvent) => void}) {
  // Separate optimistic tasks from those with pull requests
  const optimisticTasks = useMemo(() => tasks.filter(task => task.isOptimistic), [tasks]) as OptimisticTask[]
  const hydratedTasks = useMemo(
    () =>
      tasks.filter(task => {
        if (task.isOptimistic) return false
        return task.pull || task.nwo || task.id
      }) as HydratedTask[],
    [tasks],
  )
  const currentRepo = useCurrentRepository()

  const viewAllTasksUrl = useMemo(() => {
    const url = new URL('/copilot/agents', window.location.origin)
    if (currentRepo?.ownerLogin && currentRepo?.name) {
      // Properly encode owner and name to prevent URL injection, preserving the slash
      const repoParam = `${encodeURIComponent(currentRepo.ownerLogin)}/${encodeURIComponent(currentRepo.name)}`
      return `${url.pathname}?repo=${repoParam}`
    }
    return url.pathname
  }, [currentRepo])

  return (
    <ActionList showDividers className={styles.tasksList}>
      <ActionList.Group>
        <ActionList.GroupHeading as="h3" className={styles.tasksListHeading}>
          Recent sessions{' '}
          {tasks && tasks.length !== 0 && (
            <Link
              href={viewAllTasksUrl}
              className={styles.viewAllLink}
              onClick={e => {
                sendEvent('agent_sessions.global_agents_menu', {
                  target: 'VIEW_ALL_TASKS_LINK',
                })
                onLinkClick(e)
              }}
            >
              View all
            </Link>
          )}
        </ActionList.GroupHeading>

        {optimisticTasks.map(task => (
          <OptimisticTaskItem key={task.clientGeneratedId} task={task} />
        ))}
        {hydratedTasks.map(task => {
          return (
            <TaskItem
              key={task.clientGeneratedId ?? task.id ?? task.resource_id}
              taskId={task.id}
              isArchived={!!task.archived_at}
              state={task.latest_session_state}
              updatedAt={task.latest_session_updated_at}
              title={getTaskTitle(task, task.pull?.title)}
              prState={task.pull?.state}
              prNumber={task.pull?.number}
              nwo={task.nwo}
              prGlobalId={task.pull?.global_relay_id}
              prInMergeQueue={task.pull?.inMergeQueue ?? false}
              latestSessionId={task.latest_session_id}
              onLinkClick={onLinkClick}
              agentSlug={task.agentSlug}
              sharingStatus={task.sharing_status}
            />
          )
        })}
      </ActionList.Group>
    </ActionList>
  )
}

function OptimisticTaskItem({task}: {task: OptimisticTask}) {
  return (
    <ActionList.Item className={styles.task} disabled aria-label={`Creating task in ${task.nwo}`} size="large">
      <ActionList.LeadingVisual className={styles.optimisticTaskIcon}>
        <DotFillIcon />
      </ActionList.LeadingVisual>
      <WithShimmerEffect className={styles.shimmeringTaskTitle}>{task.problemStatement}</WithShimmerEffect>
      <ActionList.Description variant="block" className="no-wrap">
        {task.nwo}
      </ActionList.Description>
    </ActionList.Item>
  )
}

function TasksLoadingState() {
  return (
    <ActionList showDividers className={styles.tasksList}>
      <ActionList.Group>
        <ActionList.GroupHeading as="h3" className={styles.tasksListHeading}>
          {/* This matches the width of the "Recent" header in the populated list */}
          {/* We show it as a Skeleton so we don’t flash the text in case it resolves to an empty/error state */}
          {/* eslint-disable-next-line primer-react/no-system-props */}
          <SkeletonText size="bodySmall" width="4.75rem" />
        </ActionList.GroupHeading>
        {Array.from({length: 3}, (_, index) => (
          <ActionList.Item disabled key={index} size="large">
            <ActionList.LeadingVisual>
              <SkeletonAvatar size={16} />
            </ActionList.LeadingVisual>
            {/* eslint-disable-next-line primer-react/no-system-props */}
            <SkeletonText maxWidth="75%" />
            <ActionList.Description variant="block">
              {/* eslint-disable-next-line primer-react/no-system-props */}
              <SkeletonText size="bodySmall" maxWidth="50%" />
            </ActionList.Description>
          </ActionList.Item>
        ))}
      </ActionList.Group>
    </ActionList>
  )
}

function TasksEmptyState() {
  return (
    <MessageState
      heading="Start a new task with Copilot"
      description="Describe your task in natural language. Copilot will work in the background and open a pull request for your review."
      linkHref="https://docs.github.com/copilot/concepts/coding-agent/coding-agent"
      linkText={'Learn more about Copilot cloud agent'}
    />
  )
}

function TasksErrorState() {
  return (
    <MessageState
      showAlertIcon
      heading="Tasks couldn’t be loaded"
      description="Try again or, if the problem persists, contact support."
      linkHref="https://githubstatus.com/"
      linkText="GitHub status"
    />
  )
}

function MessageState({
  showAlertIcon = false,
  heading,
  description,
  linkHref,
  linkText,
}: {
  showAlertIcon?: boolean
  heading: string
  description: string
  linkHref?: string
  linkText?: string
}) {
  return (
    <div className={styles.messageState}>
      <h3 className={styles.messageStateHeading}>
        {showAlertIcon && <AlertIcon className="var(--fgColor-attention)" />}
        {heading}
      </h3>
      <p className={styles.messageStateDescription}>{description}</p>
      {linkHref && linkText && (
        <Link href={linkHref} inline className="d-inline-block">
          {linkText}
        </Link>
      )}
    </div>
  )
}

function CopilotDisclosure() {
  return (
    <div className={styles.copilotDisclosure}>
      <p className={styles.copilotDisclosureText}>
        <Link
          href="https://docs.github.com/copilot/responsible-use/copilot-coding-agent"
          target="_blank"
          rel="noopener noreferrer"
          muted
          inline
        >
          Copilot
        </Link>{' '}
        uses AI. Check for mistakes.
      </p>
    </div>
  )
}
